

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('083749fb-5c95-4cc7-ac5b-be152db71378', '2026-05-22 07:27:57.328', NULL, 'Vua Trần Thái Tông tiến hành nghi lễ tế Giao tại đàn tế ngoại ô kinh thành Thăng Long, chính thức khẳng định thiên mệnh của triều Trần trước toàn thể quốc dân.', '1226-02-15', 'Trần Thái Tông làm lễ tế Trời Đất');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('b6d9ad8b-ec7f-4026-a8b4-78ee1499a9dd', '2026-05-22 07:27:57.328', NULL, 'Cựu hoàng hậu triều Lý (mẹ của Lý Chiêu Hoàng) chính thức rời hoàng cung Thăng Long để xuất gia tu hành, khép lại một chương lịch sử của triều đại cũ.', '1227-04-12', 'Hoàng thái hậu triều Lý xuất gia');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('c4e8f534-6341-4a90-8488-1d956b1ad6ec', '2026-05-22 07:27:57.328', NULL, 'Thái sư Trần Thủ Độ chỉ đạo biên soạn và ban hành bộ Quốc triều thông chế nhằm luật hóa các quy định hành chính, quan chế và luật pháp của vương triều Trần.', '1230-03-22', 'Ban hành bộ Quốc triều thông chế');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('346cc000-c470-4834-b6b8-f6d4e73a08ff', '2026-05-22 07:27:57.328', NULL, 'Nhà Trần cải tổ hệ thống hành chính địa phương, đổi tên các đơn vị hương, giáp từ thời Lý thành đơn vị xã, đặt chức Xã quan để quản lý dân cư.', '1231-05-18', 'Đổi các hương, giáp thành xã');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('8b37cba6-fef3-4357-a86b-33340d9d2340', '2026-05-22 07:27:57.328', NULL, 'Triều đình nhà Trần tổ chức khoa thi Thái học sinh (tương đương Tiến sĩ) đầu tiên nhằm tuyển chọn nhân tài rộng rãi trong nhân dân, không phân biệt xuất thân.', '1232-08-25', 'Mở khoa thi Thái học sinh đầu tiên');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('4083a079-81cf-4ba4-97d3-4231210bfe48', '2026-05-22 07:27:57.328', NULL, 'Vua Trần Thái Tông cho lập Thẩm hình viện, một cơ quan tư pháp chuyên trách việc xét xử và rà soát lại các vụ án oan sai trong cả nước.', '1236-11-05', 'Thành lập Thẩm hình viện');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('d27edc42-044a-4679-8b42-a1112bcd517b', '2026-05-22 07:27:57.328', NULL, 'Do mâu thuẫn gia đình và triều chính, Phụng Càn vương Trần Liễu (anh trai vua) đem quân khởi loạn trên sông Cái nhưng sau đó được Trần Thủ Độ và vua giảng hòa.', '1237-05-14', 'Sự biến sông Cái của Trần Liễu');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('be79fb5c-7b36-4144-94ad-03737f2acebc', '2026-05-22 07:27:57.328', NULL, 'Nhà Trần thực hiện cải cách hành chính quy mô lớn, chia toàn bộ lãnh thổ quốc gia thành 12 lộ, đặt các chức An phủ sứ để cai trị tinh gọn hơn.', '1242-02-10', 'Chia nước Đại Việt thành 12 lộ');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('10ee3299-7005-4545-8703-d61e5b0dae10', '2026-05-22 07:27:57.328', NULL, 'Triều đình ban hành chỉ dụ quy định các khoa thi Hương tại địa phương sẽ được tổ chức định kỳ 7 năm một lần để tạo nguồn cử tử cho thi hội.', '1244-09-11', 'Quy định luật thi hương định kỳ');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('bd275383-9ab0-471f-988f-84751ea4d6f3', '2026-05-22 07:27:57.328', NULL, 'Nhà Trần chính thức định ra danh hiệu Tam khôi (Trạng nguyên, Bảng nhãn, Thám hoa) cho ba người đỗ cao nhất trong khoa thi Đình.', '1246-06-20', 'Định lệ thi Tam khôi thời Trần');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('242a4df6-c010-4751-ac48-bd3530608a14', '2026-05-22 07:27:57.328', NULL, 'Khoa thi Định năm Đinh Mùi ghi danh Thần đồng Nguyễn Hiền đỗ Trạng nguyên khi mới 12 tuổi, trở thành vị Trạng nguyên trẻ tuổi nhất trong lịch sử Việt Nam.', '1247-08-15', 'Nguyễn Hiền đỗ Trạng nguyên năm 12 tuổi');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('f9e3085b-d9c8-4951-8a4e-fb9cf8bfc263', '2026-05-22 07:27:57.328', NULL, 'Nhà Trần ra lệnh cho các lộ đắp đê từ đầu nguồn đến bờ biển để ngăn lũ lụt, gọi là đê Quai Vạc, đồng thời đặt chức Hà đê sứ để trông nom.', '1248-03-05', 'Khởi công đắp đê Quai Vạc');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('6e4689cb-2b44-405a-9af6-071944e2583c', '2026-05-22 07:27:57.328', NULL, 'Do Chiêm Thành thường xuyên quấy nhiễu biên giới phía Nam, vua Trần Thái Tông trực tiếp cầm quân đi trừng phạt để giữ vững bình yên vùng biên ải.', '1252-01-30', 'Trần Thái Tông thân chinh phạt Chiêm Thành');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('db7c729b-b246-4ff8-ba3b-4c15f19cae11', '2026-05-22 07:27:57.328', NULL, 'Triều đình cho xây dựng Giảng võ đường tại Thăng Long làm nơi huấn luyện quân sự cao cấp, tập hợp binh pháp và rèn luyện võ nghệ cho các tướng lĩnh.', '1253-08-24', 'Thành lập Giảng võ đường');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('fb3602a9-7a87-4c14-a0d7-84ab2df8e2eb', '2026-05-22 07:27:57.328', NULL, 'Nhà Trần cho lập Quốc học viện và đúc tượng Chu Công, Khổng Tử để làm nơi giảng dạy kinh sách kinh điển, thúc đẩy Nho học phát triển mạnh mẽ.', '1253-10-15', 'Sáng lập Quốc học viện Thăng Long');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('4316a90c-a7a8-4b81-99e7-653f98500423', '2026-05-22 07:27:57.328', NULL, 'Triều đình chia ngạch Trạng nguyên thành hai loại: Kinh trạng nguyên (cho người vùng đồng bằng) và Trại trạng nguyên (cho người vùng thanh nghệ biên viễn).', '1256-04-11', 'Quy định lệ thi chọn Kinh trạng nguyên');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('8cbd1946-bc67-4365-a079-8ecf82ca2931', '2026-05-22 07:27:57.328', NULL, 'Quân xâm lược Mông Cổ áp sát biên giới, vua Trần Thái Tông trực tiếp ngự giá chỉ huy trận Bình Lệ Nguyên. Nghe lời khuyên của Lê Tần, vua chủ động rút lui bảo toàn lực lượng.', '1257-12-12', 'Trận chiến Bình Lệ Nguyên anh dũng');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('7468b187-ac21-4f95-955b-8f3497fb487d', '2026-05-22 07:27:57.328', NULL, 'Nhà Trần cho xây dựng hành cung Thiên Trường (Nam Định) - quê hương bản quán của dòng họ Trần, biến nơi đây thành kinh đô thứ hai sau Thăng Long.', '1262-03-14', 'Xây dựng hành cung Thiên Trường');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('1aa9484a-f331-41aa-abec-b4ddc1bcd174', '2026-05-22 07:27:57.328', NULL, 'Nhà Trần ban chiếu ban quyền cho các công chúa, vương hầu chiêu mộ dân nghèo phiêu tán đi khai hoang vùng ven biển, lập nên các điền trang quy mô lớn.', '1266-02-28', 'Cho phép vương hầu khai hoang lập điền trang');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('1fdf9348-2ae5-404e-876c-b670877fe243', '2026-05-22 07:27:57.328', NULL, 'Hàn lâm viện Học sĩ Lê Văn Hưu dâng lên vua Trần Thánh Tông bộ ''Đại Việt Sử ký'' gồm 30 quyển. Đây là bộ chính sử đầu tiên mang tính bước ngoặt của nền sử học nước nhà.', '1272-03-20', 'Lê Văn Hưu hoàn thành Đại Việt Sử Ký');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('aa0478a8-3eb1-4cfe-b0d0-5e01e383eff9', '2026-05-22 07:27:57.328', NULL, 'Vua Trần Thánh Tông xuống chiếu cho phép hàng vạn người Hoa từ phương Bắc chạy trốn ách thống trị của quân Nguyên được định cư tại vùng ven biển Đại Việt.', '1274-10-05', 'Tiếp nhận người Tống tị nạn Nguyên');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('d6ef48b9-97d4-4477-9ba4-2b29ff96b30a', '2026-05-22 07:27:57.328', NULL, 'Hưng Đạo Vương Trần Quốc Tuấn tổ chức đại diễn trận và duyệt binh tại vùng chiến lược Vạn Kiếp, chuẩn bị tinh thần kháng chiến cho toàn quân.', '1275-06-18', 'Trần Quốc Tuấn duyệt binh tại Vạn Kiếp');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('fa782609-113c-4abb-9879-9b520a66d44e', '2026-05-22 07:27:57.328', NULL, 'Sứ giả nhà Nguyên là Sài Thung dẫn đầu đoàn bộ hạ nghênh ngang tiến vào Thăng Long nhằm uy hiếp, bắt ép vua Trần sang chầu Hốt Tất Liệt.', '1281-05-12', 'Sứ giả nhà Nguyên Sài Thung tới Thăng Long');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('3cc9ad65-8857-44be-86a4-e21aea8223cd', '2026-05-22 07:27:57.328', NULL, 'Trước nguy cơ xâm lược cận kề từ nhà Nguyên, vua Trần Nhân Tông phong Trần Quốc Tuấn làm Quốc công Tiết chế, thống lĩnh toàn bộ quân đội Đại Việt.', '1283-07-22', 'Trần Quốc Tuấn làm Quốc công Tiết chế');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('4d95213f-37fb-430d-8a55-692dd8189897', '2026-05-22 07:27:57.328', NULL, 'Để cổ vũ tinh thần yêu nước và ý chí quyết chiến của binh sĩ trước cuộc chiến sinh tử, Trần Quốc Tuấn viết bài ''Hịch tướng sĩ'' lay động lòng người.', '1284-09-30', 'Trần Quốc Tuấn soạn Hịch tướng sĩ');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('55c68cb1-4eda-4a48-9b59-2af61568cbd2', '2026-05-22 07:27:57.328', NULL, 'Vua Trần Nhân Tông triệu tập các bậc phụ lão trong cả nước về điện Diên Hồng để hỏi kế đánh giặc. Điện Diên Hồng vang dội tiếng hô đồng thanh: ''ĐÁNH!''.', '1285-01-10', 'Hội nghị Diên Hồng lịch sử khai mạc');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('e70f5fda-8743-4c19-99c1-81bc7ea04ac7', '2026-05-22 07:27:57.328', NULL, 'Chiêu Văn vương Trần Nhật Duật chỉ huy liên quân Đại Việt đánh tan quân Nguyên do Toa Đô chỉ huy tại cửa Hàm Tử, bẻ gãy một cánh quân chủ lực của địch.', '1285-05-25', 'Đại thắng Hàm Tử quan vang dội');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('fb2033d0-9171-4cb8-947d-0d59e905548d', '2026-05-22 07:27:57.328', NULL, 'Thượng tướng Trần Quang Khải tổng chỉ huy trận công kích thần tốc vào bến Chương Dương, đánh bại thủy quân Nguyên, mở đường giải phóng hoàn toàn kinh thành Thăng Long.', '1285-06-10', 'Đại thắng Chương Dương độ giải phóng Thăng Long');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('5da5e321-8777-4555-a385-2c75064a93df', '2026-05-22 07:27:57.328', NULL, 'Bị quân Trần truy kích dữ dội ở biên giới phía Bắc, trấn nam vương Thoát Hoan của nhà Nguyên phải chui vào ống đồng để quân lính khiêng chạy trốn thoát thân.', '1285-06-28', 'Thoát Hoan chui ống đồng trốn về nước');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('1838bc3a-8e6f-4532-9a14-362f2aa34eee', '2026-05-22 07:27:57.328', NULL, 'Nuốt hận bại trận, Hốt Tất Liệt điều động Thoát Hoan dẫn 30 vạn đại quân cùng hàng trăm chiến thuyền ồ ạt tràn qua biên giới Đại Việt lần thứ ba.', '1287-11-20', 'Thoát Hoan dẫn quân Nguyên xâm lược lần 3');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('47a126e6-74a4-49ee-9b83-3b4e3e69b713', '2026-05-22 07:27:57.328', NULL, 'Phó tướng Trần Khánh Dư mai phục và đánh tan đoàn thuyền lương khổng lồ của Trương Văn Hổ tại Vân Đồn, cắt đứt hoàn toàn nguồn lương nhu yếu tử huyệt của quân Nguyên.', '1288-01-15', 'Trần Khánh Dư đại thắng Vân Đồn');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('66efbcd1-2e37-4099-bc00-8c442c57ff7f', '2026-05-22 07:27:57.328', NULL, 'Vua Trần Nhân Tông xét duyệt và ban thưởng tước vị cao quý cho các công thần có công lao vĩ đại trong hai cuộc kháng chiến chống Nguyên Mông thần thánh.', '1289-05-02', 'Đại định công thần kháng chiến chống Nguyên');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('21fd5afa-72c7-4532-9de6-682f88219bb5', '2026-05-22 07:27:57.328', NULL, 'Nhà Trần thực hiện sách lược ngoại giao mềm dẻo sau chiến tranh, đón tiếp sứ bộ nhà Nguyên sang nối lại bang giao hòa bình trên thế ngẩng cao đầu.', '1292-04-18', 'Tiếp đón phái đoàn ngoại giao Nguyên');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('599847df-6fbb-4986-8dc2-7de6933c701f', '2026-05-22 07:27:57.328', NULL, 'Vua Trần Nhân Tông nhường ngôi cho Thái tử Trần Thuyên (Trần Anh Tông), lui về ngự ở hành cung Vũ Lâm Ninh Bình rồi lên núi Yên Tử tu hành.', '1293-03-09', 'Trần Nhân Tông nhường ngôi cho Trần Anh Tông');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('44919740-54bf-450d-a574-01b717f210ba', '2026-05-22 07:27:57.328', NULL, 'Phật hoàng Trần Nhân Tông chính thức thống nhất các dòng thiền cũ để khai sáng ra Thiền phái Trúc Lâm Yên Tử - dòng thiền thuần Việt mang đậm tinh thần nhập thế.', '1299-10-24', 'Trần Nhân Tông sáng lập Thiền phái Trúc Lâm');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('2732be30-cafc-4c2c-ba1b-0314fabd6ed4', '2026-05-22 07:27:57.328', NULL, 'Trong chuyến du hành hóa độ tại phương Nam, Phật hoàng đến Chiêm Thành và hứa gả công chúa Huyền Trân cho Quốc vương Chế Mân để kết tình hòa hảo.', '1301-06-05', 'Phật hoàng Trần Nhân Tông du ngoạn Chiêm Thành');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('0affc4a3-8647-4f84-913c-8c87285678ca', '2026-05-22 07:27:57.328', NULL, 'Triều đình tổ chức khoa thi lớn, chọn được danh sĩ Mạc Đĩnh Chi đỗ Trạng nguyên. Ông là người có tướng mạo xấu xí nhưng tài năng xuất chúng, danh chấn hai nước.', '1304-03-12', 'Khoa thi Thái học sinh tuyển chọn Mạc Đĩnh Chi');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('981802c3-7127-4607-b0f8-c77c7455999f', '2026-05-22 07:27:57.328', NULL, 'Vua Trần Anh Tông nhường ngôi cho Thái tử Trần Mạnh (Trần Minh Tông). Tân vương là người có lòng nhân hậu, trọng dụng các bậc hiền thần như Chu Văn An.', '1314-04-03', 'Trần Anh Tông nhường ngôi cho Trần Minh Tông');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('f942beaf-ac4d-4a4a-9413-80989880ac79', '2026-05-22 07:27:57.328', NULL, 'Thái thượng hoàng Trần Anh Tông - vị vua có công giữ vững kỷ cương triều chính và bảo vệ biên cương vững chắc - qua đời tại cung Trùng Quang.', '1320-05-17', 'Thượng hoàng Trần Anh Tông băng hà');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('a6533a7d-f576-4541-b842-b396b4867ebb', '2026-05-22 07:27:57.328', NULL, 'Vua Trần Minh Tông ra lệnh khảo hạch nghiêm ngặt đức tài của toàn bộ quan lại từ trung ương đến địa phương nhằm loại bỏ những kẻ tham nhũng, lười biếng.', '1323-09-08', 'Khảo hạch quan lại toàn quốc');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('ab9106a4-6b42-4b9d-a1ae-e28a943633f8', '2026-05-22 07:27:57.328', NULL, 'Vua Trần Minh Tông nhường ngôi cho con trai mới 10 tuổi là Trần Vượng (Trần Hiến Tông) nhằm giữ vững truyền thống lưỡng đầu chế bảo hộ hoàng tộc.', '1329-02-15', 'Trần Minh Tông nhường ngôi cho Trần Hiến Tông');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('87fa7d91-bdc6-46da-a354-c33a91aedb11', '2026-05-22 07:27:57.328', NULL, 'Thượng hoàng Trần Minh Tông dù tuổi cao vẫn quyết định ngự giá thân chinh tiến quân vào vùng biên giới phía Tây đánh dẹp quân Ai Lao quấy nhiễu dân lành.', '1335-11-22', 'Trần Minh Tông thân chinh dẹp loạn Ai Lao');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
